<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from "vue"
const activeIndex=ref(0);const root=ref(null);const paused=ref(false);const visible=ref(false);const reduced=window.matchMedia("(prefers-reduced-motion: reduce)").matches;let timer;let observer
