const active=computed(()=>features[activeIndex.value]);const stop=()=>{if(timer){clearInterval(timer);timer=null}};const start=()=>{stop();if(!reduced&&visible.value&&!paused.value)timer=setInterval(()=>activeIndex.value=(activeIndex.value+1)%features.length,4800)};const choose=(index)=>{activeIndex.value=index;start()};const pause=()=>{paused.value=true;stop()};const resume=()=>{paused.value=false;start()};onMounted(()=>{observer=new IntersectionObserver(([entry])=>{visible.value=entry.intersectionRatio>=.3;visible.value?start():stop()},{threshold:[.3]});observer.observe(root.value)});onBeforeUnmount(()=>{stop();observer?.disconnect()})
</script>
